contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address to, uint256 value) public {
        require(to != address(0));
        uint256 balFromBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        bool ok = c.transfer(to, value); if (__ESBMC_reverted()) return;
        uint256 balFromAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balToAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;
        assert(ok == true && balFromAfter + value == balFromBefore && balToAfter == balToBefore + value);
    }
}

